/// <summary>
/// Extension of class SalesFormLetter_Confirm
/// </summary>
[ExtensionOf(classStr(SalesFormLetter))]
final class AVASalesFormLetter_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method main
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args  _args)
{
    Common          avaRecord      = _args.record();
    DocumentStatus  avaParmEnum    = _args.parmEnum();

    next main(_args);

    if(avaParmEnum == DocumentStatus::PackingSlip
        || avaParmEnum == DocumentStatus::Confirmation)
    {
        FormDataUtil::getFormDataSource(avaRecord).refresh();
    }
}
